library(ggplot2);library(dplyr);library(scales)
o<-file.path("reports","eda");dir.create(o,recursive=T,showWarnings=F)
c<-read.csv("data/processed/sme_credit_clean.csv",stringsAsFactors=F);m<-read.csv("data/processed/sme_credit_modeling.csv",stringsAsFactors=F);c$application_date<-as.Date(c$application_date)
stopifnot(nrow(c)==10000,nrow(m)==6373,sum(m$default_flag)==1350)
band<-function(x,b,l){factor(cut(x,b,l,right=F),levels=l)};m$bureau_band<-band(m$bureau_score_imputed,c(-Inf,550,650,700,750,Inf),c("<550","550-649","650-699","700-749","750+"));m$dti_band<-band(m$debt_to_income_ratio,c(-Inf,.2,.35,.5,Inf),c("<20%","20%-34.99%","35%-49.99%","50%+"));m$age_band<-band(m$business_age_years,c(-Inf,3,5,10,Inf),c("<3 years","3-4.99 years","5-9.99 years","10+ years"));m$lr_band<-band(m$loan_to_annual_revenue_ratio,c(-Inf,.15,.25,.4,Inf),c("<15%","15%-24.99%","25%-39.99%","40%+"));m$amt_band<-band(m$requested_loan_amount,c(-Inf,25000,50000,100000,Inf),c("<25k","25k-49.99k","50k-99.99k","100k+"))
n<-c("business_age_years","number_of_employees_imputed","monthly_revenue","annual_revenue","requested_loan_amount","loan_tenure_months","existing_loans","existing_monthly_debt","debt_to_income_ratio","bureau_score_imputed","credit_history_years","previous_defaults","collateral_value_imputed","bank_account_age_years_imputed","loan_to_annual_revenue_ratio","collateral_coverage_ratio","monthly_debt_to_revenue_ratio","revenue_per_employee","requested_amount_per_tenure_month")
z<-bind_rows(lapply(n,function(x){v=m[[x]];data.frame(variable=x,count=sum(!is.na(v)),mean=mean(v,na.rm=T),median=median(v,na.rm=T),sd=sd(v,na.rm=T),min=min(v,na.rm=T),p25=quantile(v,.25,na.rm=T),p75=quantile(v,.75,na.rm=T),max=max(v,na.rm=T))}));write.csv(z,file.path(o,"numeric_summary.csv"),row.names=F)
rate<-function(x)m%>%group_by(.data[[x]])%>%summarise(loans=n(),defaults=sum(default_flag),default_rate=mean(default_flag),.groups="drop")%>%rename(segment=1)%>%mutate(segment=as.character(segment))
v<-c("bureau_band","dti_band","age_band","has_previous_default","business_type","loan_purpose","lr_band","amt_band");r<-bind_rows(lapply(v,function(x)transform(rate(x),variable=x)));write.csv(r,file.path(o,"default_rate_tables.csv"),row.names=F)
cv<-c("bureau_score_imputed","debt_to_income_ratio","business_age_years","loan_to_annual_revenue_ratio","collateral_coverage_ratio","monthly_debt_to_revenue_ratio");co<-cor(m[cv],use="pairwise.complete.obs");write.csv(co,file.path(o,"correlation_matrix.csv"))
save<-function(p,x)ggsave(file.path(o,x),p,width=8,height=5,dpi=120)
mo<-c%>%mutate(month=format(application_date,"%Y-%m"))%>%group_by(month)%>%summarise(applications=n(),approval=mean(application_status%in%c("Approved","Disbursed")),disb=mean(application_status=="Disbursed"))
save(ggplot(mo,aes(month,applications))+geom_col()+theme_minimal()+theme(axis.text.x=element_text(angle=45,hjust=1)),"01_applications_by_month.png");save(ggplot(mo,aes(month,approval))+geom_col()+scale_y_continuous(labels=percent)+theme_minimal(),"02_approval_rate_by_month.png");save(ggplot(mo,aes(month,disb))+geom_col()+scale_y_continuous(labels=percent)+theme_minimal(),"03_disbursement_rate_by_month.png")
for(q in c("application_status","business_type","loan_purpose"))save(ggplot(c,aes(.data[[q]]))+geom_bar()+theme_minimal()+theme(axis.text.x=element_text(angle=35,hjust=1)),paste0("bar_",q,".png"))
for(q in c("requested_loan_amount","approved_amount"))save(ggplot(c,aes(.data[[q]]))+geom_histogram(bins=40)+theme_minimal(),paste0("hist_",q,".png"))
for(q in v){a<-rate(q);save(ggplot(a,aes(segment,default_rate))+geom_col()+scale_y_continuous(labels=percent)+theme_minimal()+theme(axis.text.x=element_text(angle=35,hjust=1)),paste0("risk_",q,".png"))}
save(ggplot(as.data.frame(as.table(co)),aes(Var1,Var2,fill=Freq))+geom_tile()+theme_minimal(),"correlation_heatmap.png")
ts<-bind_rows(lapply(c("business_type","loan_purpose","has_previous_default"),function(x){a<-chisq.test(table(m[[x]],m$default_flag));data.frame(test="Chi-square",variable=x,statistic=a$statistic,p_value=a$p.value,n=nrow(m))}),lapply(c("bureau_score_imputed","debt_to_income_ratio","business_age_years","loan_to_annual_revenue_ratio"),function(x){a<-wilcox.test(m[[x]]~m$default_flag);data.frame(test="Wilcoxon",variable=x,statistic=a$statistic,p_value=a$p.value,n=nrow(m))}));write.csv(ts,file.path(o,"statistical_tests.csv"),row.names=F)
p<-rate("has_previous_default");b<-rate("bureau_band");f<-c(sprintf("Disbursed population: 6,373 loans with %.2f%% defaults.",100*mean(m$default_flag)),sprintf("Prior-default rate: %.2f%% versus %.2f%%.",100*p$default_rate[p$segment==1],100*p$default_rate[p$segment==0]),sprintf("Bureau-band rates range from %.2f%% to %.2f%%.",100*min(b$default_rate),100*max(b$default_rate)),"Synthetic data; associations do not prove causation.","Application status is current/final state.","Performance is a snapshot, not monthly history.","Post-disbursement and workflow outcomes are excluded from predictor recommendations.","Default modeling has not been performed.");writeLines(f,file.path(o,"management_findings.txt"));cat("EDA PASS\nplots:",length(list.files(o,pattern="png$")),"tables: 4 tests:",nrow(ts),"findings:",length(f),"\n")